-- Update bid statuses for awarded tenders
UPDATE bids SET status = 'awarded' WHERE bid_reference IN ('BID-NT2021-0001-001', 'BID-DOT2021-0012-001', 'BID-DOH2021-0023-001', 'BID-DBE2021-0034-001', 'BID-DWS2021-0045-001', 'BID-COT2022-0056-001', 'BID-ETH2022-0067-001', 'BID-DOH2022-0078-001', 'BID-DHS2022-0089-001', 'BID-DOT2022-0100-001', 'BID-DHE2023-0111-001', 'BID-DOH2023-0122-001', 'BID-DWS2023-0133-001', 'BID-DMR2023-0144-001', 'BID-DSD2023-0155-001');

-- Insert Contract Awards referencing the winning bids
ON CONFLICT (contract_number) DO UPDATE SET total_paid = EXCLUDED.total_paid, total_variations = EXCLUDED.total_variations;